		to = from
	}
	if to-from+1 > readFileLineBudget {
		to = from + readFileLineBudget - 1
		out.Truncated = true
	}
	body := strings.Join(lines[from-1:to], "\n")
	if len(body) > readFileByteBudget {
		body = body[:readFileByteBudget]
		out.Truncated = true
	}
	out.Content, out.StartLine, out.EndLine = body, from, to
	if out.Truncated {
		out.Diagnostics = append(out.Diagnostics, fmt.Sprintf("truncated: returned lines %d-%d of %d; request a narrower range with startLine and endLine.", from, to, len(lines)))
	}
	if out.Redacted {
		out.Diagnostics = append(out.Diagnostics, "security: a credential-like value was masked before returning this file.")
	}
	return out, nil
}

// fileBody reassembles the stored chunks and falls back to a live read for files
// whose content the index policy skipped.
개인키 블록은 파일 전체를 차단하고 자격증명 대입문과 클라우드 접근 키는 청크 저장
전에 `[REDACTED]`로 치환한다. URL에 박힌 자격증명(`https://user:token@host`,
`mongodb://`, `sqlserver://` 등 스킴 무관), Oracle thin 서술자(`scott/tiger@`),
XML 설정의 `<password>`·`name="password" value="..."` 쌍, `Authorization` 헤더,
`curl -u user:pass`, `.netrc`의 `login ... password ...`도 함께 치환한다. 값이 다음
줄부터 이어지는 YAML 블록 스칼라(`password: |`, `client_secret: >-`)는 들여쓰기가
키 이하로 얕아지는 줄 전까지 본문을 줄마다 치환해 줄 수를 그대로 둔다. 호스트는
남긴다 — 어느 시스템의 자격증명인지가 조치의 출발점이기 때문이다. 탐지 경로와 조치는
`index_security_events`에 기록되지만 탐지된 원문은 기록하지 않는다.

마스킹 규칙은 지문으로 관리한다. 규칙이 바뀌면 지문이 바뀌고, 커밋이 그대로여도 모든
ref를 다시 읽는다. 이미 저장된 청크는 저장 당시 규칙으로만 가려져 있으므로, 규칙 개선의
효과는 재색인 뒤에 나타난다.

